export class ParseError extends Error {}
const fail = (m) => { throw new ParseError(m) }

const isWs = (c) => c === ' ' || c === '\t'
const isBare = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)
const D = '\\d+(?:_\\d+)*'
const INT = new RegExp(`^[+-]?${D}$`)
const FLOAT = new RegExp(`^[+-]?${D}(?:\\.${D}(?:[eE][+-]?${D})?|[eE][+-]?${D})$`)

const newTable = () => ({ t: 'table', m: new Map(), made: false })

class Line {
  constructor(s) { this.s = s; this.i = 0 }
  ws() { while (isWs(this.s[this.i])) this.i++ }
  // at end of line content (end, or a comment)
  atEnd() { const c = this.s[this.i]; return c === undefined || c === '#' || c === ';' }
  peek() { return this.s[this.i] }
}

function parseQuoted(L) {
  const q = L.s[L.i++]
  let out = ''
  if (q === "'") {
    const j = L.s.indexOf("'", L.i)
    if (j < 0) fail('unterminated string')
    out = L.s.slice(L.i, j)
    L.i = j + 1
    return out
  }
  for (;;) {
    const c = L.s[L.i]
    if (c === undefined) fail('unterminated string')
    if (c === '"') { L.i++; return out }
    if (c === '\\') {
      L.i++
      const e = String.fromCodePoint(L.s.codePointAt(L.i) ?? fail('unterminated string'))
      L.i += e.length
      if (e === '"') out += '"'
      else if (e === '\\') out += '\\'
      else if (e === 'n') out += '\n'
      else if (e === 't') out += '\t'
      else if (e === 'r') out += '\r'
      else if (e === '0') out += '\0'
      else if (e === 'u') {
        const h = L.s.slice(L.i, L.i + 4)
        if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        L.i += 4
      } else fail('invalid escape \\' + e)
      continue
    }
    out += c
    L.i++
  }
}

function parseName(L) {
  const c = L.peek()
  if (c === '"' || c === "'") return parseQuoted(L)
  const st = L.i
  while (isBare(L.s[L.i])) L.i++
  if (L.i === st) fail('expected a name')
  return L.s.slice(st, L.i)
}

function parseDotted(L) {
  L.ws()
  const keys = [parseName(L)]
  for (;;) {
    L.ws()
    if (L.peek() !== '.') return keys
    L.i++
    L.ws()
    keys.push(parseName(L))
  }
}

function parseValue(L, base) {
  L.ws()
  if (L.atEnd()) fail('expected a value')
  const c = L.peek()
  if (c === ',' || c === ']' || c === '}') fail('expected a value')
  if (c === '"' || c === "'") return { t: 'string', v: parseQuoted(L) }
  if (c === '[') {
    L.i++
    const items = []
    L.ws()
    for (;;) {
      L.ws()
      if (L.atEnd()) fail('unterminated array')
      if (L.peek() === ']') { L.i++; break }
      items.push(parseValue(L, base))
      L.ws()
      if (L.atEnd()) fail('unterminated array')
      if (L.peek() === ',') { L.i++; continue }
      if (L.peek() === ']') { L.i++; break }
      fail('unterminated array')
    }
    return { t: 'array', items, aot: false }
  }
  if (c === '{') {
    L.i++
    const tbl = newTable()
    L.ws()
    if (L.peek() === '}') { L.i++; return tbl }
    for (;;) {
      L.ws()
      if (L.atEnd()) fail('unterminated inline table')
      const keys = parseDotted(L)
      L.ws()
      if (L.peek() !== '=') fail('expected = in an inline table')
      L.i++
      const v = parseValue(L, [...base, ...keys])
      assign(tbl, base, keys, v)
      L.ws()
      if (L.atEnd()) fail('unterminated inline table')
      if (L.peek() === ',') { L.i++; continue }
      if (L.peek() === '}') { L.i++; break }
      fail('unterminated inline table')
    }
    return tbl
  }
  const st = L.i
  while (L.i < L.s.length && !isWs(L.s[L.i]) && !',]}'.includes(L.s[L.i])) L.i++
  const w = L.s.slice(st, L.i)
  if (w === 'true' || w === 'false') return { t: 'boolean', v: w === 'true' }
  if (INT.test(w)) return { t: 'integer', v: Number(w.replace(/_/g, '')) }
  if (FLOAT.test(w)) return { t: 'float', v: Number(w.replace(/_/g, '')) }
  fail('invalid value ' + w)
}

// Walk keys[0..n-1) from tbl, creating tables; returns the table reached.
function walk(tbl, base, keys, n) {
  let cur = tbl
  for (let k = 0; k < n; k++) {
    let node = cur.m.get(keys[k])
    if (!node) { node = newTable(); cur.m.set(keys[k], node) }
    if (node.t === 'array' && node.aot) node = node.items[node.items.length - 1]
    if (node.t !== 'table') fail([...base, ...keys.slice(0, k + 1)].join('.') + ' is not a table')
    cur = node
  }
  return cur
}

function assign(tbl, base, keys, v) {
  const parent = walk(tbl, base, keys, keys.length - 1)
  const last = keys[keys.length - 1]
  if (parent.m.has(last)) fail(`key ${[...base, ...keys].join('.')} is defined twice`)
  parent.m.set(last, v)
}

function parseHeader(L, root) {
  const aot = L.s[L.i + 1] === '['
  L.i += aot ? 2 : 1
  const keys = parseDotted(L)
  L.ws()
  const close = aot ? ']]' : ']'
  if (L.s.startsWith(close, L.i)) L.i += close.length
  else fail('unterminated table header')
  L.ws()
  if (!L.atEnd()) fail('trailing text after a table header')
  const parent = walk(root, [], keys, keys.length - 1)
  const last = keys[keys.length - 1]
  const path = keys.join('.')
  const node = parent.m.get(last)
  if (aot) {
    const fresh = newTable()
    if (!node) parent.m.set(last, { t: 'array', items: [fresh], aot: true })
    else if (node.t === 'array' && node.aot) node.items.push(fresh)
    else fail(path + ' is not an array of tables')
    return { tbl: fresh, path: keys }
  }
  if (!node) {
    const t = newTable(); t.made = true
    parent.m.set(last, t)
    return { tbl: t, path: keys }
  }
  if (node.t !== 'table') fail(path + ' is not a table')
  if (node.made) fail(`table ${path} is defined twice`)
  node.made = true
  return { tbl: node, path: keys }
}

export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let cur = { tbl: root, path: [] }
  lines.forEach((raw, idx) => {
    try {
      const L = new Line(raw)
      L.ws()
      if (L.atEnd()) return
      if (L.peek() === '[') { cur = parseHeader(L, root); return }
      const keys = parseDotted(L)
      L.ws()
      if (L.peek() !== '=') fail('expected key = value')
      L.i++
      const v = parseValue(L, [...cur.path, ...keys])
      assign(cur.tbl, cur.path, keys, v)
      L.ws()
      if (!L.atEnd()) fail('trailing text after a value')
    } catch (e) {
      if (e instanceof ParseError) e.message = `line ${idx + 1}: ${e.message}`
      throw e
    }
  })
  return root
}

const cmp = (a, b) => {
  const x = Array.from(a, (c) => c.codePointAt(0)), y = Array.from(b, (c) => c.codePointAt(0))
  for (let i = 0; i < Math.min(x.length, y.length); i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}
const sortedKeys = (t) => [...t.m.keys()].sort(cmp)

export function toJson(n, ind = '') {
  const inner = ind + '  '
  if (n.t === 'table') {
    const ks = sortedKeys(n)
    if (!ks.length) return '{}'
    return '{\n' + ks.map((k) => `${inner}${JSON.stringify(k)}: ${toJson(n.m.get(k), inner)}`).join(',\n') + `\n${ind}}`
  }
  if (n.t === 'array') {
    if (!n.items.length) return '[]'
    return '[\n' + n.items.map((x) => inner + toJson(x, inner)).join(',\n') + `\n${ind}]`
  }
  return JSON.stringify(n.v)
}

export function toKeys(n, path = '', out = []) {
  const kids = n.t === 'table' ? sortedKeys(n).map((k) => [path ? path + '.' + k : k, n.m.get(k)])
    : n.t === 'array' ? n.items.map((x, i) => [`${path}[${i}]`, x]) : []
  for (const [p, c] of kids) { out.push(`${p} ${c.t}`); toKeys(c, p, out) }
  return out
}
